// writeText returns a promise, so a synchronous try/catch misses permission
// failures and the button lies about having copied. Every copy path goes
// through this and reports what actually happened.
// Copy runs synchronously inside the click, through a hidden textarea, so it
// cannot lose the race with focus. The async clipboard API is the fallback,
// not the other way round: navigator.clipboard.writeText rejects the moment
// the document is not focused, which is exactly what opening LinkedIn does.
function copyText(text) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text; ta.setAttribute('readonly', ''); ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;font-size:16px;';
    document.body.appendChild(ta);
    if (/iP(hone|ad|od)/.test(navigator.userAgent)) {   // iOS Safari needs a real range
      ta.contentEditable = 'true'; ta.readOnly = false;
      const r = document.createRange(); r.selectNodeContents(ta);
      const sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(r);
      ta.setSelectionRange(0, text.length);
    } else { ta.select(); }
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    if (ok) return Promise.resolve();
  } catch (e) {}
  if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(text);
  return Promise.reject(new Error('no clipboard'));
}
// Button feedback is always short enough to fit the pill.
